import { signal } from '@vorzelajs/core'
import { For } from '@vorzelajs/dom'
import { accessorOf } from '~/hooks/index.ts'
import { useId } from '~/hooks/use-id.ts'
import { cx } from '~/lib/cx.ts'
import type { ReactNode } from '~/lib/types.ts'
import { ChevronDown } from './icons.tsx'
import styles from './accordion.module.scss'

export type AccordionItem = {
  id: string
  title: string
  content: ReactNode
}

export interface AccordionProps {
  items: AccordionItem[] | (() => AccordionItem[])
  type?: 'single' | 'multiple'
  defaultValue?: string | string[]
  onValueChange?: (value: string[]) => void
  className?: string
}

/** A list of disclosure sections. Single mode keeps one panel open at a time. */
export function Accordion({
  items,
  type = 'single',
  defaultValue,
  onValueChange,
  className,
}: AccordionProps) {
  const baseId = useId('accordion')
  const [open, setOpen] = signal<string[]>(
    !defaultValue
      ? []
      : Array.isArray(defaultValue)
        ? defaultValue
        : [defaultValue],
  )

  const toggle = (id: string): void => {
    const current = open()
    const isOpen = current.includes(id)
    const next =
      type === 'single'
        ? isOpen
          ? []
          : [id]
        : isOpen
          ? current.filter((value) => value !== id)
          : [...current, id]

    setOpen(next)
    onValueChange?.(next)
  }

  const handleKeyDown = (event: KeyboardEvent): void => {
    const keys = ['ArrowDown', 'ArrowUp', 'Home', 'End']
    if (!keys.includes(event.key)) return

    const root = event.currentTarget as HTMLDivElement
    const triggers = Array.from(
      root.querySelectorAll<HTMLButtonElement>('[data-accordion-trigger]'),
    )
    if (triggers.length === 0) return

    const current = triggers.indexOf(event.target as HTMLButtonElement)
    if (current === -1) return

    event.preventDefault()

    let next = current
    if (event.key === 'ArrowDown') next = (current + 1) % triggers.length
    if (event.key === 'ArrowUp')
      next = (current - 1 + triggers.length) % triggers.length
    if (event.key === 'Home') next = 0
    if (event.key === 'End') next = triggers.length - 1

    triggers[next]?.focus()
  }

  return (
    <div
      className={cx(styles.root, className)}
      onKeyDown={handleKeyDown}
      data-type={type}
    >
      <For each={accessorOf<AccordionItem[]>(items)} key={(item) => item.id}>
        {(item) => {
          const triggerId = `${baseId}-${item.id}-trigger`
          const panelId = `${baseId}-${item.id}-panel`
          const isOpen = (): boolean => open().includes(item.id)

          return (
            <div
              className={styles.item}
              data-state={() => (isOpen() ? 'open' : 'closed')}
            >
              <h3 className={styles.heading}>
                <button
                  type="button"
                  id={triggerId}
                  className={styles.trigger}
                  aria-expanded={() => String(isOpen())}
                  aria-controls={panelId}
                  data-accordion-trigger
                  onClick={() => toggle(item.id)}
                >
                  <span className={styles.title}>{item.title}</span>
                  <ChevronDown className={styles.chevron} aria-hidden="true" />
                </button>
              </h3>

              <div
                id={panelId}
                role="region"
                aria-labelledby={triggerId}
                inert={() => (!isOpen() ? true : undefined)}
                className={styles.panel}
              >
                <div className={styles.panelInner}>
                  <div className={styles.content}>{item.content}</div>
                </div>
              </div>
            </div>
          )
        }}
      </For>
    </div>
  )
}

@use 'styles' as vz;

.root {
  width: 100%;
  margin: 0;
  overflow: hidden;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('xl');
  background: vz.color('card');
}

.item + .item {
  border-top: 1px solid vz.color('border');
}

.heading {
  margin: 0;
  font: inherit;
}

.trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: vz.space(3);
  width: 100%;
  padding: vz.space(3) vz.space(4);
  border: 0;
  background: transparent;
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  font-weight: 500;
  line-height: 1.35;
  text-align: left;
  cursor: pointer;
  transition: background-color vz.duration('base') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent', 0.4);
  }

  @include vz.focus-ring(2px, -2px, 0.6);
}

.title {
  min-width: 0;
}

.chevron {
  @include vz.icon(4);

  color: vz.color('muted-foreground');
  transition: transform vz.duration('slow') vz.ease('out');
}

.item[data-state='open'] .chevron {
  transform: rotate(180deg);
}

.panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows vz.duration('slow') vz.ease('in-out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.panel-inner {
  min-height: 0;
  overflow: hidden;
}

.content {
  padding: 0 vz.space(4) vz.space(4);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  line-height: 1.5;
  opacity: 0;
  transition: opacity vz.duration('slow') vz.ease('in-out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.item[data-state='open'] .panel {
  grid-template-rows: 1fr;
}

.item[data-state='open'] .content {
  opacity: 1;
}
